import type {Track} from '../../listen-upstream/realtime/planner'
import {fixture} from './fixture'
import type {LiveScene} from './live-contract'
export function liveFixture():LiveScene{const scene=fixture();return{schema:'harbeat.live-layering.v1',scope:'normal-playback-lab',producer:'jetson',approved:true,id:'b'.repeat(64),implementationSha256:'c'.repeat(64),sceneSha256:'d'.repeat(64),scene,nativeGain:.76,entry:{sourcePosition:scene.clips.aStart,fadeSeconds:.008,peak:.8},evidence:{runtime:'live-layering-linear-8ms-v1',sourceVerified:true,producerHost:'test-jetson',entryPeak:.8,exitPeaks:scene.exits.map((e:any)=>({at:e.at,bPosition:e.bPosition,peak:.8})),limitations:['fixture only']}}}
export function liveTracks(v:LiveScene=liveFixture()):{a:Track;b:Track}{return Object.fromEntries((['a','b'] as const).map(side=>{const p=v.scene.sources[side];return[side,{id:p.trackId,title:side,bpm:v.scene.bpm,duration:120,native:{url:'/listen/media/'+p.masterSha256+'.flac',sha256:p.masterSha256,bytes:100,duration:120},bars:[],windows:[],provenance:{masterSha256:p.masterSha256,reportSha256:p.reportSha256,vocalSha256:p.vocalSha256,runId:p.runId}}]})) as unknown as {a:Track;b:Track}}
